proc.on('close', code => {
  // 子进程输出分两类：单行 JSON 步骤记录 + 末尾多行 JSON 汇总对象。
  // 按花括号配对把末尾汇总对象完整截取出来，其余按行解析。
  const all = lines.join('\n') + (buffer ? '\n' + buffer : '');
  const stepRecords = [];
  let allPassed = null;
  // 从后往前找到能配对的大括号范围（最后一个顶层对象）
  const linesArr = all.split('\n').map(l => l.trim()).filter(Boolean);
  let summaryText = null;
