import { spawn } from 'node:child_process';
import { appendFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const logFile = path.join(__dirname, 'agh_scenario_run.jsonl');
const proc = spawn('node', ['agh_scenario_run.mjs'], { cwd: __dirname, stdio: ['ignore', 'pipe', 'inherit'] });
let buffer = '';
const lines = [];
proc.stdout.on('data', chunk => {
  buffer += chunk.toString();
  const next = buffer.split(/\r?\n/);
  buffer = next.pop();
  for (const line of next) if (line.trim()) lines.push(line.trim());
});
proc.on('close', code => {
  const stepRecords = [];
  let allPassed = null;
  const remaining = [...lines];
  if (buffer.trim()) remaining.push(buffer.trim());

  // 子进程最后输出的是一个多行 JSON 汇总对象；其余都是单行 JSON 步骤。
  // 从末尾用花括号配对截取汇总对象。
  const arr = [...remaining];
  let summaryText = null;
  let summaryStart = -1;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (!arr[i].startsWith('{')) continue;
    let depth = 0;
    let started = false;
    let text = '';
    for (let j = i; j < arr.length; j++) {
      text += arr[j] + '\n';
      for (const ch of arr[j]) {
        if (ch === '{') { depth++; started = true; }
        else if (ch === '}') { depth--; }
      }
      if (started && depth === 0) { summaryText = text.trim(); summaryStart = i; break; }
    }
    if (summaryText !== null) break;
  }
  const stepLines = summaryStart === -1 ? arr : arr.slice(0, summaryStart);

  for (const line of stepLines) {
    line = line.trim();
    if (!line) continue;
    try {
      const parsed = JSON.parse(line);
      stepRecords.push(parsed);
      if (parsed && typeof parsed === 'object' && parsed.allPassed !== undefined) allPassed = parsed.allPassed;
    } catch {
      stepRecords.push({ rawStep: line });
    }
  }
  if (summaryText) {
    try {
      const parsed = JSON.parse(summaryText);
      stepRecords.push(parsed);
      if (parsed && typeof parsed === 'object' && parsed.allPassed !== undefined) allPassed = parsed.allPassed;
    } catch {
      stepRecords.push({ rawFinal: summaryText });
    }
  }
  for (const record of stepRecords) appendFileSync(logFile, JSON.stringify(record) + '\n', { encoding: 'utf8' });
  console.log(`agh_scenario_run log written: ${logFile}`);
  console.log(`exitCode=${code} allPassed=${allPassed}`);
  process.exitCode = code;
});

