import { spawn } from 'node:child_process';
import { appendFileSync, rmSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const logFile = path.join(__dirname, 'agh_scenario_run.jsonl');
rmSync(logFile, { force: true });

// 直接 spawn 子进程并捕获 stdout。
// 子进程 agh_scenario_run.mjs 输出：
//   - 前 N 行：单行 JSON 步骤记录
//   - 末尾：一个多行 JSON 汇总对象（pretty-printed）
// 解析策略：从末尾用花括号配对截取汇总对象，其余按行 JSON.parse。

const proc = spawn('node', ['agh_scenario_run.mjs'], { cwd: __dirname, stdio: ['ignore', 'pipe', 'inherit'] });
const chunks = [];
proc.stdout.on('data', c => chunks.push(c));

proc.on('close', code => {
  const text = Buffer.concat(chunks).toString('utf8');
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const stepRecords = [];
  let allPassed = null;

  // 从后往前找花括号配对的顶层对象
  let summaryStart = -1;
  let summaryText = null;
  for (let i = lines.length - 1; i >= 0; i--) {
    if (!lines[i].startsWith('{')) continue;
    let depth = 0;
    let started = false;
    let buf = '';
    for (let j = i; j < lines.length; j++) {
      buf += lines[j] + '\n';
      for (const ch of lines[j]) {
        if (ch === '{') { depth++; started = true; }
        else if (ch === '}') { depth--; }
      }
      if (started && depth === 0) {
        summaryStart = i;
        summaryText = buf.trim();
        break;
      }
    }
    if (summaryText !== null) break;
  }

  const stepLines = summaryStart === -1 ? lines : lines.slice(0, summaryStart);

  for (const line of stepLines) {
    try {
      const obj = JSON.parse(line);
      stepRecords.push(obj);
      if (obj.allPassed !== undefined) allPassed = obj.allPassed;
    } catch {
      stepRecords.push({ rawStep: line });
    }
  }

  if (summaryText !== null) {
    try {
      const obj = JSON.parse(summaryText);
      stepRecords.push(obj);
      if (obj.allPassed !== undefined) allPassed = obj.allPassed;
    } catch {
      stepRecords.push({ rawFinal: summaryText });
    }
  }

  for (const record of stepRecords) {
    appendFileSync(logFile, JSON.stringify(record) + '\n', { encoding: 'utf8' });
  }

  console.log(`agh_scenario_run log written: ${logFile} (${stepRecords.length} records)`);
  console.log(`exitCode=${code} allPassed=${allPassed}`);
  process.exitCode = code;
});

