import { spawn } from 'node:child_process';
import { appendFileSync, rmSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const logFile = path.join(__dirname, 'agh_scenario_run.jsonl');
rmSync(logFile, { force: true });

const proc = spawn('node', ['agh_scenario_run.mjs'], { cwd: __dirname, stdio: ['ignore', 'pipe', 'inherit'] });
let raw = '';
proc.stdout.on('data', chunk => {
  raw += chunk.toString('utf8');
});

proc.on('close', code => {
  const records = [];
  let allPassed = null;
  let i = 0;

  const parseAt = () => {
    while (i < raw.length && /\s/.test(raw[i])) i++;
    if (i >= raw.length) return null;
    const start = i;
    const depth = raw.slice(start, i + 4096).search(/[^{}\[\]"]/) === -1 ? 0 : 0;
    let valueStart = i;
    let inString = false;
    let escaped = false;
    let stack = [];
    for (; i < raw.length; i++) {
      const ch = raw[i];
      if (inString) {
        if (escaped) escaped = false;
        else if (ch === '\\') escaped = true;
        else if (ch === '"') inString = false;
        continue;
      }
      if (ch === '"') inString = true;
      if (ch === '{' || ch === '[') stack.push(ch);
      if (ch === '}' || ch === ']') {
        stack.pop();
        if (stack.length === 0) {
          const text = raw.slice(valueStart, i + 1);
          const parsed = JSON.parse(text);
          return parsed;
        }
      }
    }
    throw new Error('unterminated JSON value at index ' + valueStart);
  };

  while (i < raw.length) {
    if (/\s/.test(raw[i])) { i++; continue; }
    const parsed = parseAt();
    records.push(parsed);
    if (parsed && typeof parsed === 'object' && 'allPassed' in parsed) allPassed = parsed.allPassed;
  }

  for (const record of records) appendFileSync(logFile, JSON.stringify(record) + '\n', { encoding: 'utf8' });
  console.log(`agh_scenario_run log written: ${logFile} (${records.length} records)`);
  console.log(`exitCode=${code} allPassed=${allPassed}`);
  process.exitCode = code;
});

