proc.on('close', code => {
  const stepRecords = [];
  let allPassed = null;
  const remaining = [...lines];
  if (buffer.trim()) remaining.push(buffer.trim());
  while (remaining.length) {
    const joined = remaining.join('\n');
    const first = joined.trim();
    if (!first) break;
    try {
      const parsed = JSON.parse(first);
      stepRecords.push(parsed);
      if (Array.isArray(parsed)) {
        for (const item of parsed) if (item && item.allPassed !== undefined) allPassed = item.allPassed;
      } else if (parsed && typeof parsed === 'object' && parsed.allPassed !== undefined) {
        allPassed = parsed.allPassed;
      }
      break;
    } catch {
      if (remaining.length === 1) {
        stepRecords.push({ rawFinal: first });
        break;
      }
      stepRecords.push({ rawStep: remaining.shift() });
    }
  }
  for (const record of stepRecords) appendFileSync(logFile, JSON.stringify(record) + '\n', { encoding: 'utf8' });
  console.log(`agh_scenario_run log written: ${logFile}`);
  console.log(`exitCode=${code} allPassed=${allPassed}`);
  process.exitCode = code;
});

